DELIMITER $$
CREATE PROCEDURE USP_TEST_I(
    IN p_TEST_TYPE INT,
    IN p_HOST_IDEN INT,
    IN p_TEST_RESULT TEXT,
    IN p_TEST_DATE DATETIME
)
BEGIN
    INSERT INTO test (TEST_TYPE, HOST_IDEN, TEST_RESULT, TEST_DATE)
    VALUES (p_TEST_TYPE, p_HOST_IDEN, p_TEST_RESULT, p_TEST_DATE);
    
    -- Return the auto-generated TEST_IDEN
    SELECT LAST_INSERT_ID() AS TEST_IDEN;
END$$
DELIMITER ;
